            oc,ocl=ol
            if len(ocl)!=len(cl): continue
            or0=min(x for x,y in ocl); oc_=min(y for x,y in ocl)
            dr=or0-r0; dc=oc_-c0
            if set((x+dr,y+dc) for x,y in cl)==set(map(tuple,ocl)): found=(int(dr),int(dc),(or0,oc_))
        # hole depth = min distance from any hole cell to outside the bbox? just use nh
        inf='TOP' if r0<H/3 else ('MID' if r0<H*2/3 else 'BOT')
        outf='TOP' if found[2][0]<H/3 else ('MID' if found[2][0]<H*2/3 else 'BOT')
