import collections
def comps(g,v):
    seen=set(); res=[]
    H=len(g);W=len(g[0])
    for i,r in enumerate(g):
        for j,x in enumerate(r):
            if x!=v or (i,j) in seen: continue
            st=[(i,j)]; cells=[]
            while st:
                a,b=st.pop()
                if not(0<=a<H and 0<=b<W) or g[a][b]!=v or (a,b) in seen: continue
                seen.add((a,b)); cells.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)): st.append((a+da,b+db))
            res.append(cells)
    return res
