import os,glob,re,numpy as np,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
ti=np.array(G['Test input']); print(ti.shape, ti.tolist())

import numpy as np,collections
ti=np.array(G['Test input'])
def solve(inp):
    a=np.array(inp); h,w=a.shape
    # flood from border over zeros
    from collections import deque
    seen=np.zeros_like(a,bool); dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if a[i,j]==0 and not seen[i,j]: seen[i,j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if a[i,j]==0 and not seen[i,j]: seen[i,j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and a[ni,nj]==0 and not seen[ni,nj]:
                seen[ni,nj]=True; dq.append((ni,nj))
    out=a.copy()
    for i in range(h):
        for j in range(w):
            if a[i,j]==0 and not seen[i,j]:
                # find nearest nonzero neighbor color
                nbrs=[a[ni,nj] for ni in range(max(0,i-1),min(h,i+2)) for nj in range(max(0,j-1),min(w,j+2)) if (ni,nj)!=(i,j)]
                out[i,j]=nbrs[0]
    return out.tolist()
res=solve(ti)
print(np.array(res).shape)
print(json.dumps(res))
